#include <bits/stdc++.h>
using namespace std;

// 座位在「本侧序列」里的下标：左侧 A B C，右侧 D F
int pos(char ch) {
    if (ch == 'A') return 1;
    if (ch == 'B') return 2;
    if (ch == 'C') return 3;
    if (ch == 'D') return 1;
    return 2;                              // 'F'
}

// 过道左侧是 A B C，右侧是 D F
bool leftSide(char ch) {
    return ch == 'A' || ch == 'B' || ch == 'C';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string c1, s1, c2, s2;
    cin >> c1 >> s1 >> c2 >> s2;

    bool q1 = (c1 == c2);                                   // ① 同车厢
    bool q2 = q1 && s1.substr(0, 2) == s2.substr(0, 2);     // ② 同排（必须与 q1 相与）
    bool q3 = q2 && leftSide(s1[2]) == leftSide(s2[2]);     // ③ 同侧
    bool q4 = q3 && abs(pos(s1[2]) - pos(s2[2])) == 1;      // ④ 同侧序列中相邻

    cout << q1 << q2 << q3 << q4 << '\n';                   // bool 默认输出 1/0
    return 0;
}
